metric_card.react_example:
const MetricCard = ({ title, value, change, changeType, chart }) => (
  <div className="bg-white rounded-lg shadow-sm border border-slate-200 p-6">
    <div className="flex items-center justify-between mb-4">
      <h3 className="text-sm font-medium text-slate-600 uppercase tracking-wide">{title}</h3>
    </div>
    <div className="text-3xl font-bold text-slate-900">{value}</div>
    <div className={`flex items-center text-sm mt-2 ${
      changeType === 'positive' ? 'text-green-600' : 
      changeType === 'negative' ? 'text-red-600' : 'text-slate-500'
    }`}>
      {change}
    </div>
    {chart && <div className="mt-4 h-16">{chart}</div>}
  </div>
)

sidebar_navigation.react_example:
const SidebarNav = ({ items, activeItem }) => (
  <nav className="py-4">
    {items.map((item) => (
      <a
        key={item.id}
        href={item.href}
        className={`flex items-center px-6 py-3 ${
          activeItem === item.id
            ? 'bg-blue-50 text-blue-700 border-r-2 border-blue-700'
            : 'text-slate-700 hover:bg-slate-50 hover:text-slate-900'
        }`}
      >
        <item.icon className={`w-5 h-5 mr-3 ${item.color}`} />
        <span className="font-medium">{item.label}</span>
      </a>
    ))}
  </nav>
)

button_system.react_example:
const Button = ({ variant = 'primary', size = 'md', outline = false, children, ...props }) => {
  const baseClasses = 'inline-flex items-center justify-center rounded font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2';
  const sizeClasses = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2 text-sm',
    lg: 'px-6 py-3 text-base'
  };
  const variantClasses = {
    primary: outline ? 'border border-blue-600 text-blue-600 hover:bg-blue-50' : 'bg-blue-600 text-white hover:bg-blue-700'
  };

  return (
    <button className={`${baseClasses} ${sizeClasses[size]} ${variantClasses[variant]}`} {...props}>
      {children}
    </button>
  );
};

